import React, { useState } from 'react';

export default function Book() {
  const [friends, setFriends] = useState([
    { name: 'Sangavi', balance: -70 },
    { name: 'Max', balance: -180 },
    { name: 'Annie', balance: 10 },
    { name: 'Rajeshwari', balance: 1500 }
  ]);

  const [bill, setBill] = useState('');
  const [yourExp, setYourExp] = useState('');
  const [payer, setPayer] = useState('you'); // NEW: who paid the bill

  const selected = 'Max'; // static selected friend

  function splitBill() {
    const total = parseFloat(bill);
    const yours = parseFloat(yourExp);
    const theirs = total - yours;

    if (isNaN(total) || isNaN(yours) || yours > total) {
      alert("Enter valid numbers. Your share can't exceed the total bill.");
      return;
    }

    let balanceChange = 0;

    if (payer === 'you') {
      balanceChange = theirs; // friend owes you
    } else {
      balanceChange = -yours; // you owe friend
    }

    setFriends(prev =>
      prev.map(friend =>
        friend.name === selected
          ? { ...friend, balance: friend.balance + balanceChange }
          : friend
      )
    );

    // Reset fields
    setBill('');
    setYourExp('');
    setPayer('you');
  }

  const friendExp = bill && yourExp ? parseFloat(bill) - parseFloat(yourExp) : '';

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: 'center', color: '#333' }}>🍲 Bill Splitter 💸</h1>

      <ul style={{ padding: 0 }}>
        {friends.map((f) => (
          <li
            key={f.name}
            style={{
              background: '#fff',
              padding: '10px',
              marginBottom: '10px',
              borderRadius: '5px',
              borderLeft: f.name === selected ? '5px solid #007bff' : '5px solid transparent'
            }}
          >
            <strong>{f.name}</strong>:&nbsp;
            {f.balance < 0
              ? <span style={{ color: 'red' }}>You owe ₹{-f.balance}</span>
              : f.balance > 0
              ? <span style={{ color: 'green' }}>{f.name} owes you ₹{f.balance}</span>
              : <span style={{ color: 'gray' }}>Settled up</span>}
          </li>
        ))}
      </ul>

      {selected && (
        <div style={cardStyle}>
          <h2 style={{ color: '#007bff' }}>Split A Bill With {selected}</h2>

          <input
            type="number"
            placeholder="Bill Value (₹)"
            value={bill}
            onChange={e => setBill(e.target.value)}
            style={inputStyle}
          />

          <input
            type="number"
            placeholder="Your Expense (₹)"
            value={yourExp}
            onChange={e => setYourExp(e.target.value)}
            style={inputStyle}
          />

          <input
            type="number"
            placeholder="Friend's Expense (₹)"
            value={friendExp}
            readOnly
            style={{ ...inputStyle, backgroundColor: '#e9ecef', cursor: 'not-allowed' }}
          />

          <select
            value={payer}
            onChange={(e) => setPayer(e.target.value)}
            style={inputStyle}
          >
            <option value="you">You Paid the Bill</option>
            <option value="friend">Friend Paid the Bill</option>
          </select>

          <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
            <button onClick={splitBill} style={buttonStyle}>
              Split Bill
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// Styles
const containerStyle = {
  fontFamily: 'Arial, sans-serif',
  maxWidth: '600px',
  margin: 'auto',
  padding: '30px',
  background: '#f7f7f7',
  borderRadius: '10px',
  boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
};

const cardStyle = {
  background: '#fff',
  padding: '20px',
  borderRadius: '8px',
  marginTop: '20px'
};

const inputStyle = {
  display: 'block',
  width: '100%',
  padding: '10px',
  marginBottom: '10px',
  fontSize: '16px',
  borderRadius: '5px',
  border: '1px solid #ccc'
};

const buttonStyle = {
  padding: '10px 30px',
  fontSize: '16px',
  backgroundColor: '#007bff',
  color: '#fff',
  border: 'none',
  borderRadius: '5px',
  cursor: 'pointer'
};
